-- app.py creates these SQLite tables automatically.\nCREATE TABLE IF NOT EXISTS security_events (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, source_ip TEXT NOT NULL, endpoint TEXT NOT NULL, input_value TEXT NOT NULL, risk_level TEXT NOT NULL, matched_rules TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Detected');\nCREATE TABLE IF NOT EXISTS demo_records (id INTEGER PRIMARY KEY AUTOINCREMENT, full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, department TEXT NOT NULL);\n